namespace OC\Icons;

use OCP\Icons\IIconManager;
use OCP\IURLGenerator;

/**
 * Icons are static files generated by build/generate-icons.mjs:
 * core/img/icons/{name}.svg for every icon, core/img/icons.svg as sprite of the most used icons
 * and core/img/icons.json with the content hash and the names of the sprite icons.
 */
class IconManager implements IIconManager {
	private const ICON_NAME_PATTERN = '/^[a-z0-9_]{1,64}$/';

	private string $imagePath;
	/** @var array{hash: string, sprite: list<string>}|null */
	private ?array $manifest = null;

	public function __construct(
		private IURLGenerator $urlGenerator,
		?string $imagePath = null,
	) {
		$this->imagePath = $imagePath ?? \OC::$SERVERROOT . '/core/img';
	}

	#[\Override]
	public function iconExists(string $name): bool {
		return preg_match(self::ICON_NAME_PATTERN, $name) === 1
			&& is_file($this->imagePath . '/icons/' . $name . '.svg');
	}

	#[\Override]
	public function getIconUrl(string $name, bool $absolute = false): ?string {
		if (!$this->iconExists($name)) {
			return null;
		}

		$url = str_replace('{name}', $name, $this->getIconUrlTemplate());
		return $absolute ? $this->urlGenerator->getAbsoluteURL($url) : $url;
	}

	/**
	 * Information needed by the frontend to resolve icon names to URLs.
	 *
	 * @return array{iconUrl: string, spriteUrl: string, spriteIcons: list<string>}
	 */
	public function getInitialState(): array {
		$manifest = $this->getManifest();
		return [
			'iconUrl' => $this->getIconUrlTemplate(),
			'spriteUrl' => $this->urlGenerator->getWebroot() . '/core/img/icons.svg?v=' . $manifest['hash'],
			'spriteIcons' => $manifest['sprite'],
		];
	}

	private function getIconUrlTemplate(): string {
		return $this->urlGenerator->getWebroot() . '/core/img/icons/{name}.svg?v=' . $this->getManifest()['hash'];
	}

	/**
	 * @return array{hash: string, sprite: list<string>}
	 */
	private function getManifest(): array {
		if ($this->manifest === null) {
			$file = $this->imagePath . '/icons.json';
			$manifest = is_file($file) ? json_decode((string)file_get_contents($file), true) : null;
			$this->manifest = [
				'hash' => (string)($manifest['hash'] ?? ''),
				'sprite' => array_values(array_filter(
					(array)($manifest['sprite'] ?? []),
					fn (mixed $name): bool => is_string($name) && preg_match(self::ICON_NAME_PATTERN, $name) === 1,
				)),
			];
		}
		return $this->manifest;
	}
}
